import{_ as a,o as r,c as t,ag as s}from"./chunks/framework.DEqXEGcv.js";const o="/images/issues/032/cover-golden-gate.jpg",i="/images/issues/032/theme-railway-signals.jpg",l="/images/issues/032/theme-control-room.jpg",n="/images/issues/032/theme-port.jpg",p="/images/issues/032/news-opentelemetry.jpg",h="/images/issues/032/news-playwright.png",c="/images/issues/032/news-sigstore.jpg",m="/images/issues/032/world-zhijin-cave.jpg",g="/images/issues/032/world-ferrari-world.jpg",d="/images/issues/032/world-caspian.jpg",u="/images/issues/032/world-yongle-bell.jpg",_="/images/issues/032/world-antarctica.jpg",b="/images/issues/032/tool-otel-collector.jpg",f="/images/issues/032/tool-grafana.png",q="/images/issues/032/tool-trivy.png",k="/images/issues/032/tool-scorecard.png",y="/images/issues/032/recommend-chernobyl.jpg",A=JSON.parse('{"title":"小七的周刊（第 032 期）：当 AI 开始动手，观测就不能缺席","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"小七的周刊（第 032 期）：当 AI 开始动手，观测就不能缺席"}],["meta",{"property":"og:description","content":"从可观测性、浏览器自动化到软件供应链，本期讨论如何让会行动的系统留下可追溯证据。"}],["meta",{"property":"og:image","content":"/images/issues/032/cover-golden-gate.jpg"}],["meta",{"property":"og:image:alt","content":"第 032 期封面图：金门大桥"}],["meta",{"property":"og:url","content":"https://blog.leeseven.com/issues/issue-032"}]]},"headers":[],"relativePath":"issues/issue-032.md","filePath":"issues/issue-032.md","lastUpdated":1791764581000}'),P={name:"issues/issue-032.md"};function x(w,e,v,S,j,T){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="小七的周刊-第-032-期-当-ai-开始动手-观测就不能缺席" tabindex="-1">小七的周刊（第 032 期）：当 AI 开始动手，观测就不能缺席 <a class="header-anchor" href="#小七的周刊-第-032-期-当-ai-开始动手-观测就不能缺席" aria-label="Permalink to &quot;小七的周刊（第 032 期）：当 AI 开始动手，观测就不能缺席&quot;">​</a></h1><p><em>这里记录每周值得分享的科技内容，<strong>每周一发布</strong>（北京时间 07:00）。</em></p><h2 id="本期-3-个要点" tabindex="-1">本期 3 个要点 <a class="header-anchor" href="#本期-3-个要点" aria-label="Permalink to &quot;本期 3 个要点&quot;">​</a></h2><ol><li><strong>会行动的系统，首先要会留下证据</strong>：日志、链路和操作记录决定了自动化出错后能否复盘。</li><li><strong>浏览器自动化正在变成基础能力</strong>：真正的门槛不是点按钮，而是权限、状态和失败处理。</li><li><strong>供应链的安全感来自可验证来源</strong>：签名、锁文件和构建记录要成为发布流程的一部分。</li></ol><h2 id="封面图" tabindex="-1">封面图 <a class="header-anchor" href="#封面图" aria-label="Permalink to &quot;封面图&quot;">​</a></h2><p><img src="'+o+'" alt="金门大桥"></p><p>封面图：金门大桥。跨越并不只靠跨度，也靠持续检测和维护；自动化系统同样需要能看见自己的运行状态。</p><h2 id="本周短谈" tabindex="-1">本周短谈 <a class="header-anchor" href="#本周短谈" aria-label="Permalink to &quot;本周短谈&quot;">​</a></h2><h3 id="_1-速度越快-越需要一条时间线" tabindex="-1">1. 速度越快，越需要一条时间线 <a class="header-anchor" href="#_1-速度越快-越需要一条时间线" aria-label="Permalink to &quot;1. 速度越快，越需要一条时间线&quot;">​</a></h3><p><img src="'+i+'" alt="铁路信号灯"></p><p>AI agent 从“给建议”走向“执行任务”后，最容易被低估的不是模型能力，而是过程可见性。一次调用涉及提示、工具、权限、外部响应和最终写入，任何一环出错都可能只留下一个模糊的失败结果。把 trace id 贯穿请求，把关键决策和工具参数记录下来，再为敏感动作保留人工确认，排查才不会退化成猜测。小团队未必需要昂贵平台，但至少要能回答：谁在什么时候，以什么输入，调用了什么动作。</p><h3 id="_2-自动化不是把人从流程里删除" tabindex="-1">2. 自动化不是把人从流程里删除 <a class="header-anchor" href="#_2-自动化不是把人从流程里删除" aria-label="Permalink to &quot;2. 自动化不是把人从流程里删除&quot;">​</a></h3><p><img src="'+l+'" alt="电站控制室"></p><p>最成熟的自动化系统往往不是“全自动”，而是把人的注意力放到少数高价值判断上。部署机器人可以自动跑检查，但生产变更仍应有清楚的边界；客服 agent 可以整理上下文，但退款和身份变更应有可撤销路径。真正值得测量的指标也不只是成功率，还包括误操作恢复时间、人工接管比例和不可逆动作数量。对低风险、重复性任务可以放大权限，对高风险任务则宁愿慢一点。</p><h3 id="_3-来源链条会成为产品体验的一部分" tabindex="-1">3. 来源链条会成为产品体验的一部分 <a class="header-anchor" href="#_3-来源链条会成为产品体验的一部分" aria-label="Permalink to &quot;3. 来源链条会成为产品体验的一部分&quot;">​</a></h3><p><img src="'+n+'" alt="集装箱港口"></p><p>软件依赖、模型权重和数据集都像一条供应链：最终用户看到的是成品，但风险可能藏在上游。锁定版本只是起点，构建系统还要记录来源、生成时间和校验结果。对个人项目，先从 lockfile、依赖审计和发布清单开始；对团队，则把 provenance 作为构建产物一起保存。它不能保证没有漏洞，却能让“出了问题找不到谁改的”变成可解决的问题。</p><h2 id="科技与-ai-动态" tabindex="-1">科技与 AI 动态 <a class="header-anchor" href="#科技与-ai-动态" aria-label="Permalink to &quot;科技与 AI 动态&quot;">​</a></h2><h3 id="_1-opentelemetry-把观测数据推向统一语义" tabindex="-1">1. <a href="https://opentelemetry.io/" target="_blank" rel="noreferrer">OpenTelemetry 把观测数据推向统一语义</a> <a class="header-anchor" href="#_1-opentelemetry-把观测数据推向统一语义" aria-label="Permalink to &quot;1. [OpenTelemetry 把观测数据推向统一语义](https://opentelemetry.io/)&quot;">​</a></h3><p><img src="'+p+'" alt="网络拓扑示意"></p><p>【事实】OpenTelemetry 持续推进 traces、metrics 和 logs 的统一采集与传输规范，已经成为跨语言、跨厂商观测的共同接口。它解决的是“数据怎么离开应用并被统一理解”，不是替你自动解释业务故障。</p><p>【推测】随着 agent 调用链变长，统一上下文会比单一平台的漂亮仪表盘更重要。落地时先为一条关键用户路径补齐 trace，再决定要不要扩大采集范围；过早全量采集，成本和噪声都可能失控。</p><h3 id="_2-playwright-继续降低浏览器测试与自动化门槛" tabindex="-1">2. <a href="https://playwright.dev/" target="_blank" rel="noreferrer">Playwright 继续降低浏览器测试与自动化门槛</a> <a class="header-anchor" href="#_2-playwright-继续降低浏览器测试与自动化门槛" aria-label="Permalink to &quot;2. [Playwright 继续降低浏览器测试与自动化门槛](https://playwright.dev/)&quot;">​</a></h3><p><img src="'+h+'" alt="浏览器窗口"></p><p>【事实】Playwright 提供跨浏览器自动化、追踪记录和并行测试能力，常被用于端到端测试，也被用于需要浏览器交互的工作流。它让“能操作网页”更容易，但登录态、验证码和外部页面变化仍然是工程问题。</p><p>【推测】浏览器 agent 的竞争会从点击准确率转向失败后是否能解释和恢复。开发者可以先把它限制在测试环境，保存 trace 和截图，并为每个外部动作设置超时与撤销策略。</p><h3 id="_3-sigstore-让无密钥签名更接近日常发布" tabindex="-1">3. <a href="https://www.sigstore.dev/" target="_blank" rel="noreferrer">Sigstore 让无密钥签名更接近日常发布</a> <a class="header-anchor" href="#_3-sigstore-让无密钥签名更接近日常发布" aria-label="Permalink to &quot;3. [Sigstore 让无密钥签名更接近日常发布](https://www.sigstore.dev/)&quot;">​</a></h3><p><img src="'+c+'" alt="挂锁与钥匙"></p><p>【事实】Sigstore 通过短期身份、透明日志和无密钥签名，降低了开源项目验证制品来源的门槛。签名能回答“谁的工作流生成了它”，不能回答“代码本身是否没有漏洞”。</p><p>【推测】未来的软件安装体验会更自然地包含来源证明。团队不必一次性重做所有流水线，可以先给发布制品签名，再逐步把构建环境、依赖清单和验证动作纳入门禁。</p><h2 id="世界之最" tabindex="-1">世界之最 <a class="header-anchor" href="#世界之最" aria-label="Permalink to &quot;世界之最&quot;">​</a></h2><h3 id="_1-世界最长的天然拱桥-贵州织金洞天生桥" tabindex="-1">1. 世界最长的天然拱桥：贵州织金洞天生桥 <a class="header-anchor" href="#_1-世界最长的天然拱桥-贵州织金洞天生桥" aria-label="Permalink to &quot;1. 世界最长的天然拱桥：贵州织金洞天生桥&quot;">​</a></h3><p><img src="'+m+'" alt="贵州织金洞天生桥"></p><p><em>贵州织金洞的天然桥，石灰岩地貌形成的自然结构。</em></p><p>它的“最长”不是一根桥梁的单项纪录，而是多个工程系统协同的结果。复杂软件也一样，单个服务很快不代表整体可靠，接口和观测才是连接处的质量。</p><h3 id="_2-世界最大的室内主题公园-阿布扎比法拉利世界" tabindex="-1">2. 世界最大的室内主题公园：阿布扎比法拉利世界 <a class="header-anchor" href="#_2-世界最大的室内主题公园-阿布扎比法拉利世界" aria-label="Permalink to &quot;2. 世界最大的室内主题公园：阿布扎比法拉利世界&quot;">​</a></h3><p><img src="'+g+'" alt="阿布扎比法拉利世界"></p><p><em>阿布扎比法拉利世界，巨型室内空间中的主题设施。</em></p><p>高度带来风、温度和维护等额外变量。系统规模扩大后，指标不能只看峰值性能，还要关注故障传播和恢复路径。</p><h3 id="_3-世界最大的盐湖-里海" tabindex="-1">3. 世界最大的盐湖：里海 <a class="header-anchor" href="#_3-世界最大的盐湖-里海" aria-label="Permalink to &quot;3. 世界最大的盐湖：里海&quot;">​</a></h3><p><img src="'+d+'" alt="里海卫星影像"></p><p><em>从卫星视角看里海，世界面积最大的内陆水体。</em></p><p>观测能力越强，越需要过滤噪声和校准设备。日志系统也是如此：不是记录越多越好，而是要让关键异常从噪声中被看见。</p><h3 id="_4-世界最大的单体钟-明永乐大钟" tabindex="-1">4. 世界最大的单体钟：明永乐大钟 <a class="header-anchor" href="#_4-世界最大的单体钟-明永乐大钟" aria-label="Permalink to &quot;4. 世界最大的单体钟：明永乐大钟&quot;">​</a></h3><p><img src="'+u+'" alt="明永乐大钟"></p><p><em>北京大钟寺博物馆收藏的明永乐大钟。</em></p><p>单体巨物一旦成形，日常维护和状态监测就成了长期成本。自动化流程同样不能只在成功时表现良好，异常路径更值得测试。</p><h3 id="_5-世界最大的沙漠-南极冰盖" tabindex="-1">5. 世界最大的沙漠：南极冰盖 <a class="header-anchor" href="#_5-世界最大的沙漠-南极冰盖" aria-label="Permalink to &quot;5. 世界最大的沙漠：南极冰盖&quot;">​</a></h3><p><img src="'+_+'" alt="南极大陆卫星影像"></p><p><em>南极冰盖，按降水量衡量它其实属于荒漠。</em></p><p>大工程的可靠性来自持续监测、分层控制和预案，而不是建成那一刻的规模。软件平台上线后，也要把维护预算和故障演练算进总成本。</p><h2 id="工具深挖" tabindex="-1">工具深挖 <a class="header-anchor" href="#工具深挖" aria-label="Permalink to &quot;工具深挖&quot;">​</a></h2><h3 id="_1-opentelemetry-collector-把数据送到该去的地方" tabindex="-1">1. <a href="https://github.com/open-telemetry/opentelemetry-collector" target="_blank" rel="noreferrer">OpenTelemetry Collector：把数据送到该去的地方</a> <a class="header-anchor" href="#_1-opentelemetry-collector-把数据送到该去的地方" aria-label="Permalink to &quot;1. [OpenTelemetry Collector：把数据送到该去的地方](https://github.com/open-telemetry/opentelemetry-collector)&quot;">​</a></h3><p><img src="'+b+'" alt="数据中心机房"></p><p>Collector 可以在应用和后端之间承担接收、处理、采样与转发，减少业务代码直接绑定某家观测服务。它适合已经有多种语言和多个后端的团队；小项目若只有一个服务，直接使用 SDK 可能更简单。小七判断：先解决数据边界，再追求平台统一。</p><h3 id="_2-grafana-把时间线变成可读的现场" tabindex="-1">2. <a href="https://grafana.com/" target="_blank" rel="noreferrer">Grafana：把时间线变成可读的现场</a> <a class="header-anchor" href="#_2-grafana-把时间线变成可读的现场" aria-label="Permalink to &quot;2. [Grafana：把时间线变成可读的现场](https://grafana.com/)&quot;">​</a></h3><p><img src="'+f+'" alt="Grafana 仪表盘"></p><p>Grafana 擅长把指标、日志和告警放进同一观察面。它不能替团队定义什么是重要信号，所以仪表盘应围绕用户路径和服务等级目标设计，而不是把所有曲线都贴上去。适合已有数据源的团队，不适合拿来掩盖埋点缺失。</p><h3 id="_3-trivy-给容器和依赖做快速体检" tabindex="-1">3. <a href="https://github.com/aquasecurity/trivy" target="_blank" rel="noreferrer">Trivy：给容器和依赖做快速体检</a> <a class="header-anchor" href="#_3-trivy-给容器和依赖做快速体检" aria-label="Permalink to &quot;3. [Trivy：给容器和依赖做快速体检](https://github.com/aquasecurity/trivy)&quot;">​</a></h3><p><img src="'+q+'" alt="漏洞时间线示意"></p><p>Trivy 可以扫描容器镜像、文件系统和依赖中的漏洞与配置问题，适合作为 CI 的第一道反馈。扫描结果不等于风险排序，团队仍需结合是否可达、是否在生产启用和是否有修复版本来判断。先把高危结果接入发布流程，别一开始就让全部告警阻塞开发。</p><h3 id="_4-openssf-scorecard-检查开源依赖的维护信号" tabindex="-1">4. <a href="https://github.com/ossf/scorecard" target="_blank" rel="noreferrer">OpenSSF Scorecard：检查开源依赖的维护信号</a> <a class="header-anchor" href="#_4-openssf-scorecard-检查开源依赖的维护信号" aria-label="Permalink to &quot;4. [OpenSSF Scorecard：检查开源依赖的维护信号](https://github.com/ossf/scorecard)&quot;">​</a></h3><p><img src="'+k+'" alt="GitHub 标识"></p><p>Scorecard 会检查分支保护、依赖更新和工作流权限等信号，适合引入第三方依赖前做初筛。它不是安全证明，也不该取代代码审查，但能把“这个项目看起来可靠吗”变成可重复的起点。</p><h2 id="本周冷知识-彩蛋" tabindex="-1">本周冷知识 / 彩蛋 <a class="header-anchor" href="#本周冷知识-彩蛋" aria-label="Permalink to &quot;本周冷知识 / 彩蛋&quot;">​</a></h2><ul><li>🥚 <strong>冷知识</strong>：可观测性里的 trace 原本就有“追踪”之意，它不是一张报表，而是一条跨服务的事件时间线。</li><li>🧠 <strong>彩蛋</strong>：机场黑匣子并不是真的黑色，重点也不是“永远不坏”，而是事故后仍能提供证据。日志保留策略同理。</li></ul><h2 id="小七的碎碎念" tabindex="-1">小七的碎碎念 <a class="header-anchor" href="#小七的碎碎念" aria-label="Permalink to &quot;小七的碎碎念&quot;">​</a></h2><p>这周看到“全自动”三个字时，我的第一反应已经不是兴奋，而是去找回滚按钮。系统会做事当然重要，但它能不能把过程讲清楚，往往才决定人类敢不敢把下一步交给它。</p><h2 id="意外推荐-非科技" tabindex="-1">意外推荐（非科技） <a class="header-anchor" href="#意外推荐-非科技" aria-label="Permalink to &quot;意外推荐（非科技）&quot;">​</a></h2><p><strong>《切尔诺贝利的祭祷》</strong>（纪实文学）</p><p><img src="'+y+'" alt="切尔诺贝利事故纪念雕塑"></p><p><em>切尔诺贝利核事故纪念雕塑，提醒人们事故记录也是公共记忆。</em></p><p>这本书不提供工程教程，却让人看到事故如何穿过数据、制度和个人生活。对技术工作者来说，它提醒我们：指标背后总有人承担后果，设计系统时要把“谁会被影响”写进风险模型。</p><h2 id="互动钩子" tabindex="-1">互动钩子 <a class="header-anchor" href="#互动钩子" aria-label="Permalink to &quot;互动钩子&quot;">​</a></h2><blockquote><p><strong>本周问题：如果只能给一个 AI agent 增加能力，你会优先给它更大的权限，还是更完整的观测？为什么？</strong></p></blockquote><h2 id="本周行动清单" tabindex="-1">本周行动清单 <a class="header-anchor" href="#本周行动清单" aria-label="Permalink to &quot;本周行动清单&quot;">​</a></h2><ul><li>[ ] 给一条关键用户路径补上 trace id，并确认它能跨服务关联。</li><li>[ ] 为一个自动化动作记录输入、权限、结果和失败后的恢复方式。</li><li>[ ] 在 CI 中运行一次依赖或容器扫描，把结果和发布物关联起来。</li><li>[ ] 删除一个没人使用的仪表盘，换成一个能直接支持判断的告警。</li></ul><div class="issue-subscribe-cta"><h3 id="📬-喜欢这期内容" tabindex="-1">📬 喜欢这期内容？ <a class="header-anchor" href="#📬-喜欢这期内容" aria-label="Permalink to &quot;📬 喜欢这期内容？&quot;">​</a></h3><p>订阅「小七的周刊」，每周一收到最新一期。</p><div class="issue-cta-buttons"><a href="/feed.xml" class="cta-rss" target="_blank" rel="noopener noreferrer">RSS 订阅</a><a href="https://github.com/leeseven1211/blog-weekly" class="cta-share" target="_blank" rel="noopener noreferrer">GitHub</a></div></div>',78)])])}const O=a(P,[["render",x]]);export{A as __pageData,O as default};
